package com.slopeguard.model;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.*;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;

/**
 * Domain model representing an early-warning hazard alert generated by the risk assessment engine.
 * Persisted in MySQL via Spring Data JPA.
 */
@Entity
@Table(name = "early_warning_alerts")
public class EarlyWarningAlert {

    @Id
    @Column(name = "id", length = 64, nullable = false)
    private String id;

    @Column(name = "assessment_id", length = 64)
    private String assessmentId;

    @Column(name = "location_name", length = 255)
    private String locationName;

    @Column(name = "latitude", nullable = false)
    private Double latitude;

    @Column(name = "longitude", nullable = false)
    private Double longitude;

    @Enumerated(EnumType.STRING)
    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Column(name = "severity", nullable = false, length = 30)
    private AlertSeverity severity;

    @Column(name = "assessment_status", length = 50)
    private String assessmentStatus;

    @Column(name = "designation", length = 50)
    private String designation;

    @Column(name = "creation_timestamp", nullable = false)
    private LocalDateTime creationTimestamp;

    @Column(name = "updated_at", nullable = false)
    private LocalDateTime updatedAt;

    @Convert(converter = JsonMapConverter.class)
    @Column(name = "evidence_json", columnDefinition = "TEXT")
    private Map<String, Object> evidence = new HashMap<>();

    @Enumerated(EnumType.STRING)
    @JdbcTypeCode(SqlTypes.VARCHAR)
    @Column(name = "lifecycle_status", nullable = false, length = 30)
    private AlertLifecycleStatus lifecycleStatus = AlertLifecycleStatus.ACTIVE;

    @Column(name = "source", length = 255)
    private String source;

    @Column(name = "acknowledged_by_user_id")
    private Long acknowledgedByUserId;

    @Column(name = "admin_review_note", columnDefinition = "TEXT")
    private String adminReviewNote;

    public EarlyWarningAlert() {
        this.lifecycleStatus = AlertLifecycleStatus.ACTIVE;
        this.creationTimestamp = LocalDateTime.now();
        this.updatedAt = LocalDateTime.now();
    }

    public EarlyWarningAlert(String id, String locationName, Double latitude, Double longitude,
                             AlertSeverity severity, String assessmentStatus, String designation,
                             LocalDateTime creationTimestamp, Map<String, Object> evidence, String source) {
        this.id = id;
        this.locationName = locationName;
        this.latitude = latitude;
        this.longitude = longitude;
        this.severity = severity;
        this.assessmentStatus = assessmentStatus;
        this.designation = designation;
        this.creationTimestamp = creationTimestamp != null ? creationTimestamp : LocalDateTime.now();
        this.updatedAt = this.creationTimestamp;
        this.evidence = evidence != null ? evidence : new HashMap<>();
        this.source = source;
        this.lifecycleStatus = AlertLifecycleStatus.ACTIVE;
    }

    @PrePersist
    protected void onCreate() {
        if (this.creationTimestamp == null) {
            this.creationTimestamp = LocalDateTime.now();
        }
        if (this.updatedAt == null) {
            this.updatedAt = LocalDateTime.now();
        }
        if (this.lifecycleStatus == null) {
            this.lifecycleStatus = AlertLifecycleStatus.ACTIVE;
        }
    }

    @PreUpdate
    protected void onUpdate() {
        this.updatedAt = LocalDateTime.now();
    }

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getAssessmentId() {
        return assessmentId;
    }

    public void setAssessmentId(String assessmentId) {
        this.assessmentId = assessmentId;
    }

    public String getLocationName() {
        return locationName;
    }

    public void setLocationName(String locationName) {
        this.locationName = locationName;
    }

    public Double getLatitude() {
        return latitude;
    }

    public void setLatitude(Double latitude) {
        this.latitude = latitude;
    }

    public Double getLongitude() {
        return longitude;
    }

    public void setLongitude(Double longitude) {
        this.longitude = longitude;
    }

    public AlertSeverity getSeverity() {
        return severity;
    }

    public void setSeverity(AlertSeverity severity) {
        this.severity = severity;
    }

    public String getAssessmentStatus() {
        return assessmentStatus;
    }

    public void setAssessmentStatus(String assessmentStatus) {
        this.assessmentStatus = assessmentStatus;
    }

    public String getDesignation() {
        return designation;
    }

    public void setDesignation(String designation) {
        this.designation = designation;
    }

    public LocalDateTime getCreationTimestamp() {
        return creationTimestamp;
    }

    public void setCreationTimestamp(LocalDateTime creationTimestamp) {
        this.creationTimestamp = creationTimestamp;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(LocalDateTime updatedAt) {
        this.updatedAt = updatedAt;
    }

    public Map<String, Object> getEvidence() {
        return evidence;
    }

    public void setEvidence(Map<String, Object> evidence) {
        this.evidence = evidence != null ? evidence : new HashMap<>();
    }

    public AlertLifecycleStatus getLifecycleStatus() {
        return lifecycleStatus;
    }

    public void setLifecycleStatus(AlertLifecycleStatus lifecycleStatus) {
        this.lifecycleStatus = lifecycleStatus;
    }

    public String getSource() {
        return source;
    }

    public void setSource(String source) {
        this.source = source;
    }

    public Long getAcknowledgedByUserId() {
        return acknowledgedByUserId;
    }

    public void setAcknowledgedByUserId(Long acknowledgedByUserId) {
        this.acknowledgedByUserId = acknowledgedByUserId;
    }

    public String getAdminReviewNote() {
        return adminReviewNote;
    }

    public void setAdminReviewNote(String adminReviewNote) {
        this.adminReviewNote = adminReviewNote;
    }

    /**
     * JPA AttributeConverter for serializing Map<String, Object> to JSON string.
     */
    @Converter
    public static class JsonMapConverter implements AttributeConverter<Map<String, Object>, String> {
        private static final ObjectMapper MAPPER = new ObjectMapper();

        @Override
        public String convertToDatabaseColumn(Map<String, Object> attribute) {
            if (attribute == null || attribute.isEmpty()) {
                return "{}";
            }
            try {
                return MAPPER.writeValueAsString(attribute);
            } catch (JsonProcessingException e) {
                return "{}";
            }
        }

        @Override
        public Map<String, Object> convertToEntityAttribute(String dbData) {
            if (dbData == null || dbData.isBlank()) {
                return new HashMap<>();
            }
            try {
                return MAPPER.readValue(dbData, new TypeReference<Map<String, Object>>() {});
            } catch (Exception e) {
                return new HashMap<>();
            }
        }
    }
}
